import { DRAWER_EVENTS } from "../constants.js";
import { createRipple, } from "../../../core/compose/features/ripple.js";
import { setHTML } from "../../../core/dom/html.js";
import { activeElementOf } from "../../../core/dom/focus.js";
const createItemElement = (item, getClass) => {
    const el = document.createElement("button");
    el.className = getClass("drawer__item");
    el.type = "button";
    el.setAttribute("tabindex", item.disabled ? "-1" : "0");
    if (item.id) {
        el.dataset.id = item.id;
    }
    if (item.disabled) {
        el.disabled = true;
        el.setAttribute("aria-disabled", "true");
    }
    const indicator = document.createElement("span");
    indicator.className = getClass("drawer__active-indicator");
    el.appendChild(indicator);
    if (item.icon) {
        const iconEl = document.createElement("span");
        iconEl.className = getClass("drawer__item-icon");
        setHTML(iconEl, item.icon);
        iconEl.setAttribute("aria-hidden", "true");
        el.appendChild(iconEl);
    }
    if (item.label) {
        const labelEl = document.createElement("span");
        labelEl.className = getClass("drawer__item-label");
        labelEl.textContent = item.label;
        el.appendChild(labelEl);
    }
    if (item.badge) {
        const badgeEl = document.createElement("span");
        badgeEl.className = getClass("drawer__item-badge");
        badgeEl.textContent = item.badge;
        el.appendChild(badgeEl);
    }
    if (item.active) {
        el.classList.add(`${getClass("drawer__item")}--active`);
        el.setAttribute("aria-current", "page");
    }
    return el;
};
const createDividerElement = (getClass) => {
    const el = document.createElement("hr");
    el.className = getClass("drawer__divider");
    el.setAttribute("role", "separator");
    return el;
};
const createSectionElement = (item, getClass) => {
    const el = document.createElement("div");
    el.className = getClass("drawer__section-label");
    el.textContent = item.label || item.sectionLabel || "";
    return el;
};
export const withItems = (config) => (component) => {
    let currentItems = config.items || [];
    let activeId = null;
    let itemsContainer = null;
    const ripple = config.ripple !== false ? createRipple() : null;
    let rippled = [];
    const unmountRipples = () => {
        rippled.forEach((element) => ripple?.unmount(element));
        rippled = [];
    };
    const initialActive = currentItems.find((item) => item.type !== "divider" && item.type !== "section" && item.active && !item.disabled);
    if (initialActive?.id) {
        activeId = initialActive.id;
    }
    const renderItems = () => {
        if (!itemsContainer)
            return;
        unmountRipples();
        itemsContainer.replaceChildren();
        let navIndex = 0;
        currentItems.forEach((item) => {
            const type = item.type || "item";
            if (type === "divider") {
                itemsContainer.appendChild(createDividerElement(component.getClass));
                return;
            }
            if (type === "section") {
                itemsContainer.appendChild(createSectionElement(item, component.getClass));
                return;
            }
            const itemEl = createItemElement({ ...item, active: !!activeId && item.id === activeId }, component.getClass);
            itemEl.dataset.navIndex = String(navIndex);
            navIndex++;
            itemEl.addEventListener("click", (e) => {
                if (item.id && !item.disabled) {
                    setActive(item.id);
                    const selectEvent = {
                        id: item.id,
                        value: item.id,
                        label: item.label || "",
                        index: parseInt(itemEl.dataset.navIndex || "0", 10),
                        originalEvent: e,
                    };
                    component.emit(DRAWER_EVENTS.SELECT, selectEvent);
                }
            });
            if (ripple && !item.disabled) {
                ripple.mount(itemEl);
                rippled.push(itemEl);
            }
            itemsContainer.appendChild(itemEl);
        });
    };
    const setActive = (id) => {
        if (!itemsContainer)
            return;
        const activeClass = `${component.getClass("drawer__item")}--active`;
        const allItems = [...itemsContainer.querySelectorAll(`.${component.getClass("drawer__item")}`)];
        const target = allItems.find(element => element.dataset.id === id && !element.hasAttribute("disabled"));
        if (id && !target)
            return;
        allItems.forEach(element => {
            element.classList.toggle(activeClass, element === target);
            if (element === target)
                element.setAttribute("aria-current", "page");
            else
                element.removeAttribute("aria-current");
        });
        activeId = target ? id : null;
        currentItems = currentItems.map((item) => ({
            ...item,
            active: item.id === id,
        }));
    };
    const getActive = () => activeId;
    const setItems = (items) => {
        currentItems = items;
        const active = items.find((item) => item.type !== "divider" && item.type !== "section" && item.active && !item.disabled);
        activeId = active?.id || null;
        renderItems();
    };
    const getItems = () => currentItems;
    const setBadge = (id, badge) => {
        if (!itemsContainer)
            return;
        const itemEl = [...itemsContainer.querySelectorAll("[data-id]")].find(element => element.dataset.id === id);
        if (!itemEl)
            return;
        let badgeEl = itemEl.querySelector(`.${component.getClass("drawer__item-badge")}`);
        if (badge) {
            if (!badgeEl) {
                badgeEl = document.createElement("span");
                badgeEl.className = component.getClass("drawer__item-badge");
                itemEl.appendChild(badgeEl);
            }
            badgeEl.textContent = badge;
        }
        else if (badgeEl) {
            badgeEl.remove();
        }
        currentItems = currentItems.map((item) => item.id === id ? { ...item, badge } : item);
    };
    const handleKeydown = (e) => {
        if (!itemsContainer)
            return;
        const items = Array.from(itemsContainer.querySelectorAll(`.${component.getClass("drawer__item")}:not([disabled])`));
        if (!items.length)
            return;
        const currentIndex = items.indexOf(activeElementOf(itemsContainer));
        let nextIndex = -1;
        switch (e.key) {
            case "ArrowDown":
                e.preventDefault();
                nextIndex = currentIndex < items.length - 1 ? currentIndex + 1 : 0;
                break;
            case "ArrowUp":
                e.preventDefault();
                nextIndex = currentIndex > 0 ? currentIndex - 1 : items.length - 1;
                break;
            case "Home":
                e.preventDefault();
                nextIndex = 0;
                break;
            case "End":
                e.preventDefault();
                nextIndex = items.length - 1;
                break;
            case "Enter":
            case " ":
                e.preventDefault();
                if (currentIndex >= 0) {
                    items[currentIndex].click();
                }
                return;
            default:
                return;
        }
        if (nextIndex >= 0 && nextIndex < items.length) {
            items[nextIndex].focus();
        }
    };
    itemsContainer = document.createElement("div");
    itemsContainer.className = component.getClass("drawer__items");
    itemsContainer.addEventListener("keydown", handleKeydown);
    renderItems();
    return {
        ...component,
        itemsContainer,
        drawerItems: {
            setActive,
            getActive,
            setItems,
            getItems,
            setBadge,
            renderItems,
            destroy: unmountRipples,
        },
    };
};
